/**
 * Large title block that opens a page (`design/components/hero.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/hero.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { mergeProps, type JSX } from 'solid-js'

import { claimSlot, resolveSlot, scope, type Defaults } from '@polymorph/solid'
import styles from '@polymorph/recipes/structure/hero.module.css'
import Inline from '../layout/Inline'

export type HeroAlign = NonNullable<HeroProps['align']>

export interface HeroProps {
  /**
   * Buttons; the page's primary action goes here when a Hero opens the page.
   */
  actions?: JSX.Element
  align?: 'start' | 'center'
  lede?: string
  title: string
}

/** Large title block that opens a page. */
export default function Hero(given: HeroProps): JSX.Element {
  const props = mergeProps({ align: 'start' } as Defaults<HeroProps, 'align'>, claimSlot(given))
  return scope(() => {
    const actionsSlot = resolveSlot(() => props.actions)
    return (
      <section class={styles.hero} data-align={props.align} data-member="hero">
        {/* title */}
        <h1 class={styles.title}>{props.title}</h1>
        {props.lede !== undefined ? <p class={styles.lede}>{props.lede}</p> : null}
        {actionsSlot.filled() ? (
          <Inline gap={3} wrap={true} justify={props.align === 'center' ? 'center' : 'start'}>
            {actionsSlot()}
          </Inline>
        ) : null}
      </section>
    )
  })
}
